const fs = require('fs');

const [n, k] = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);

const m = Math.min(n, 13);
const fact = Array(m + 1).fill(1);

for (let i = 1; i <= m; i++) {
    fact[i] = fact[i - 1] * i;
}

if (k > fact[m]) {
    console.log(-1);
    process.exit();
}

const luckyNumbers = [];

function generateLucky(value) {
    if (value > n) return;
    if (value > 0) luckyNumbers.push(value);
    generateLucky(value * 10 + 4);
    generateLucky(value * 10 + 7);
}

generateLucky(0);

const suffixStart = n - m + 1;
let answer = 0;

for (const value of luckyNumbers) {
    if (value < suffixStart) answer++;
}

const luckySet = new Set(luckyNumbers);
const available = [];

for (let value = suffixStart; value <= n; value++) {
    available.push(value);
}

let rank = k - 1;

for (let i = 0; i < m; i++) {
    const remaining = m - i;
    const blockSize = fact[remaining - 1];
    const index = Math.floor(rank / blockSize);
    rank %= blockSize;

    const value = available.splice(index, 1)[0];
    const position = suffixStart + i;

    if (luckySet.has(position) && luckySet.has(value)) {
        answer++;
    }
}

console.log(answer);

const fs = require('fs');

const input = fs.readFileSync(0, 'utf8').trim().split(/\s+/);
const n = Number(input[0]);
const k = BigInt(input[1]);

const m = Math.min(n, 13);
const factorial = Array(m + 1).fill(1n);

for (let i = 1; i <= m; i++) {
    factorial[i] = factorial[i - 1] * BigInt(i);
}

if (k > factorial[m]) {
    console.log(-1);
    process.exit(0);
}

const start = n - m + 1;
const available = Array.from({ length: m }, (_, i) => start + i);
const permutation = [];
let rank = k - 1n;

for (let remaining = m; remaining >= 1; remaining--) {
    const blockSize = factorial[remaining - 1];
    const index = Number(rank / blockSize);
    rank %= blockSize;
    permutation.push(available.splice(index, 1)[0]);
}

function isLucky(value) {
    if (value <= 0) return false;
    while (value > 0) {
        const digit = value % 10;
        if (digit !== 4 && digit !== 7) return false;
        value = Math.floor(value / 10);
    }
    return true;
}

function countLuckyUpTo(limit) {
    let count = 0;

    function generate(value) {
        if (value > limit) return;
        count++;
        generate(value * 10 + 4);
        generate(value * 10 + 7);
    }

    if (limit >= 4) generate(4);
    if (limit >= 7) generate(7);
    return count;
}

let answer = countLuckyUpTo(start - 1);

for (let i = 0; i < m; i++) {
    const position = start + i;
    if (isLucky(position) && isLucky(permutation[i])) {
        answer++;
    }
}

console.log(answer);

